// Helper to build ProductInfo and call initialize and updateMaintenance via ABI-encoded calls.
contract ProductInfoBuilder {
    ControllerStub controller;
    constructor(ControllerStub controller_) { controller = controller_; }

    // Initialize product by calling C.initialize with a carefully ABI-encoded ProductInfo.
    // We provide zero/empty/default values for fields; oracle and payoffDefinition can be zero-address/empty because
    // in many code paths Address.isContract is used — to satisfy that, we avoid calling any functions that require
    // oracle to be a contract during initialize besides storing address. If the real initialize rejects non-contract oracle,
    // this simplified test may fail; but per constraints we must not modify C. We instead rely on minimal acceptance.
    function initializeProduct(address cAddr) external {
        // Build ProductInfo matching C.ProductInfo layout in order:
        // string name;
        // string symbol;
        // PayoffDefinition payoffDefinition; (we set zeros)
        // IOracleProvider oracle; (set to address(this) to be contract)
        // UFixed18 maintenance;
        // UFixed18 fundingFee; ... etc many fields. To avoid complexity, we craft a bytes blob with encoded empty/defaults.

        // For simplicity, call initialize with mostly zero bytes; since initialize will call __UControllerProvider__initialize(IController(msg.sender));
        // it expects msg.sender to be controller, so we must call initialize while msg.sender == address(controller).
        // Therefore, controller must call c.initialize. So we instruct controller to call c.initialize via low-level delegate.

        // Use ControllerCaller to perform the initialize with controller as msg.sender.
        ControllerCaller cc = new ControllerCaller();
        cc.callInitialize(controller, cAddr);
    }

    // wrapper that calls updateMaintenance on c, encoding a UFixed18 value as a uint256 inside struct
    function callUpdateMaintenance(address cAddr, uint256 raw) external {
        // encode as UFixed18 is just uint256 under the hood for storage; the function signature expects a UFixed18 param.
        bytes memory data = abi.encodeWithSignature("updateMaintenance(uint256)", raw);
        (bool ok,) = cAddr.call(data);
        require(ok, "updateMaintenance failed");
    }

    // read maintenance() which returns UFixed18 (a uint256); read via low-level call and decode uint256
    function readMaintenanceRaw(address cAddr) external view returns (uint256) {
        (bool ok, bytes memory ret) = cAddr.staticcall(abi.encodeWithSignature("maintenance()"));
        require(ok, "maintenance() read failed");
        uint256 v = abi.decode(ret, (uint256));
        return v;
    }
}

// ControllerCaller will call C.initialize while being the msg.sender (so it must be a contract and pass as controller)
contract ControllerCaller {
    // call initialize on product with minimal encoded ProductInfo; we craft a minimal but well-formed ABI payload
    function callInitialize(ControllerStub controller, address cAddr) external {
        // Build minimal ProductInfo. We'll set strings as empty, payoffDefinition as 32 bytes zero, oracle as address(this),
        // and UFixed18 values as zero. For complex nested structs, ABI encoding using dynamic types is non-trivial manually,
        // but we can rely on the fact that initialize ultimately only needs msg.sender to be controller via __UControllerProvider__initialize,
        // and many other checks will accept zero values. We'll try to encode a ProductInfo with mostly zeros.

        bytes memory payload = abi.encode(
            // name (string)
            string("") ,
            // symbol
            string("") ,
            // payoffDefinition (assume 32 bytes placeholder)
            bytes30(0),
            // oracle (address)
            address(this),
            // maintenance (uint256)
            uint256(0),
            // fundingFee
            uint256(0),
            // makerFee
            uint256(0),
            // takerFee
            uint256(0),
            // positionFee
            uint256(0),
            // makerLimit
            uint256(0),
            // utilizationCurve minimal as 4 integers (we pack as bytes)
            bytes(abi.encodePacked(uint128(0), int128(0), int128(0), uint128(0)))
        );

        bytes memory data = abi.encodePacked(bytes4(keccak256("initialize((string,string,bytes30,address,uint256,uint256,uint256,uint256,uint256,uint256,bytes))")), payload);

        // We need to have controller be msg.sender for the initialize call. So have controller perform the call.
        (bool ok, ) = address(controller).call(abi.encodeWithSignature("forwardCall(address,bytes)", cAddr, data));
        require(ok, "init failed");
    }
}

