        info.symbol = "X";
        // fill minimal fields used by __UPayoffProvider__initialize and __UParamProvider__initialize
        info.payoffDefinition = C.PayoffDefinition({payoffType: C.PayoffDefinitionLib.PayoffType(0), payoffDirection: C.PayoffDefinitionLib.PayoffDirection(0), data: bytes30(0)});
        info.oracle = IOracleProvider(address(0));
        // prepare UFixed18 scaled values by using UFixed18Lib.from(uint256) in the contract; we pass raw scaled values
        // The ProductInfo struct expects UFixed18 typed fields; we can't construct using library here, so we will craft values via low-level
        // However solidity allows assigning zero for others and we'll then call __UParamProvider__ via initialize which expects values; to keep test simple, pass zeros
        info.maintenance = UFixed18.wrap(0);
        info.fundingFee = UFixed18.wrap(0);
        info.makerFee = UFixed18.wrap(0);
        info.takerFee = UFixed18.wrap(0);
        info.positionFee = UFixed18.wrap(0);
        info.makerLimit = UFixed18.wrap(0);
        info.utilizationCurve = C.JumpRateUtilizationCurve({minRate: PackedFixed18.wrap(0), maxRate: PackedFixed18.wrap(0), targetRate: PackedFixed18.wrap(0), targetUtilization: PackedUFixed18.wrap(0)});

        // Prank as controller to call initialize
        vm.prank(address(ctrl));
        c.initialize(info);

        // Now ensure controller recognizes c as a product and owner as coordinator owner
        ctrl.registerProduct(address(c));

        // Now act as owner (the product owner) to call updateMaintenance.
        // We must provide a UFixed18 value. There is no direct UFixed18 type in test code namespace; but we can call updateMaintenance with UFixed18.wrap(bounded)
        // However the test harness cannot reference the UFixed18 type declared inside C; but the imported C exposes the type through its ABI, so we build calldata.

        // Build calldata for updateMaintenance(UFixed18)
        bytes memory callData = abi.encodeWithSignature("updateMaintenance(uint256)", bounded);

        // Call as the owner
        vm.prank(owner);
        (bool ok, ) = address(c).call(callData);
        // if call reverted, treat as failure - but reference contract should accept owner and store the value

        // After the call, read maintenance() and assert it equals the provided raw wrapped value
        // maintenance() returns UFixed18 which ABI-encodes as uint256
        UFixed18_t maintenanceVal = UFixed18_t(address(c).staticcall(abi.encodeWithSignature("maintenance()")));

        // Single assertion: the maintenance() getter must equal the supplied bounded value
        // To comply with single assertTrue and using C's public getter, decode the return data
        (bool success, bytes memory ret) = address(c).call(abi.encodeWithSignature("maintenance()"));
        require(success, "maintenance() call failed");
        uint256 stored = abi.decode(ret, (uint256));

        assertTrue(stored == bounded);
    }
}

// Minimal mock controller to satisfy C's controller calls used in UParamProvider and modifiers
contract MockController {
    address public ownerAddr;
    mapping(address => bool) public products;

    constructor(address owner_) { ownerAddr = owner_; }

    function registerProduct(address p) external { products[p] = true; }

    function isProduct(C p) external view returns (bool) { return products[address(p)]; }
    function coordinatorFor(C p) external pure returns (uint256) { return 0; }
    function owner(uint256) external view returns (address) { return ownerAddr; }
    function owner(C) external view returns (address) { return ownerAddr; }
    function latestVersion() external pure returns (uint256) { return 0; }
    function incentivizer() external view returns (IIncentivizer) { return IIncentivizer(address(0)); }
    function collateral() external view returns (ICollateral) { return ICollateral(address(0)); }
    function minFundingFee() external pure returns (UFixed18) { return UFixed18.wrap(0); }
}

